1	package numeric
2	
3	import (
4		"fmt"
5		"os"
6		"sync"
7		"sync/atomic"
8		"time"
9	)
10	
11	// Clock 用于注入时间来源，主要服务于确定性测试；生产代码使用墙钟。
12	type Clock interface {
13		Now() time.Time
14	}
15	
16	type wallClock struct{}
17	
18	func (wallClock) Now() time.Time { return time.Now().UTC() }
19	
20	// Option 配置 [Open] 的行为。
21	type Option func(*Store)
22	
23	// WithClock 注入自定义时钟。
24	func WithClock(c Clock) Option {
25		return func(s *Store) { s.now = c.Now }
26	}
27	
28	// Store 是本地数值作业归档：负责提交、调度、取消、查询与持久化。
29	//
30	// 一次只运行一个作业；所有方法可被多个 goroutine 并发调用。
31	// idemIdentity 是幂等作用域（提交人, 请求号）的复合键。两个字段都按调用方
32	// 给出的完整字符串逐字节参与比较，允许包含 U+0000 与非法 UTF-8 字节
33	// （后者靠记录中的 identity_raw 兜底字段跨重开保真）。不能用分隔符把两个
34	// 字段拼成单个字符串：提交人 "a"、请求号 "b\x00c" 与提交人 "a\x00b"、
35	// 请求号 "c" 在任何分隔符方案下都会产生歧义（分隔符本身可以出现在字段内部）。
36	type idemIdentity struct {
37		submitter string
38		requestID string
39	}
40	
41	type Store struct {
42		dir string
43	
44		mu     sync.Mutex
45		jobs   []*storedJob // 严格按作业号（即提交先后）排列
46		byID   map[uint64]*storedJob
47		idem   map[idemIdentity]uint64 // (提交人, 请求号) -> 作业号
48		nextID uint64
49		closed bool
50	
51		now func() time.Time
52	
53		runningID uint64
54		waitCh    chan struct{}
55		stopCh    chan struct{}
56		stopping  atomic.Bool
57		wg        sync.WaitGroup
58	
59		// compute 仅用于包内确定性测试：若为空则使用真实的 [computeResult]。
60		// 必须在任何 Submit 之前（Open 之后立即）设置；worker 只会在收到
61		// Submit 的唤醒之后读取它，因此与设置之间存在 happens-before 关系。
62		compute func(id uint64, inputs []int64, seed int64, canceled func() bool) (sum, sumSquares int64, reason string, ok bool)
63	
64		// persistFault 仅用于包内确定性测试：若非 nil，每次 persist 都会先调用它，
65		// 返回非 nil 即模拟该次记录保存失败（如同临时记录无法创建或原记录无法替换）。
66		// 生产代码恒为 nil。钩子可按作业号与“待保存的当前状态”只让某一次写入失败
67		// （例如仅让成功归档写入失败），而让其余记录照常落盘。
68		persistFault func(j *storedJob) error
69	}
70	
71	// Open 打开（必要时创建）目录 dir 并恢复其中的全部作业记录。
72	//
73	// 恢复语义：
74	//   - 已确认的提交、取消与完成结果原样保留，幂等请求号继续生效；
75	//   - 目录内两份或更多记录文件顶层保存相同作业号（文件名不同、乃至内容
76	//     完全相同）时打开失败，返回非空错误且归档对象为 nil；错误说明重复的
77	//     作业号与冲突文件名。此时不启动任何计算，也不改写目录内任何原有
78	//     记录，调用方处理冲突后再次打开才按下列规则恢复；
79	//   - 上次关闭时仍在运行的作业标记为失败（计算被中断）并阻止其下游；
80	//   - 排队作业继续排队并由本地唯一 worker 按提交先后处理；
81	//   - 成功状态始终与完整归档同时可见。
82	func Open(dir string, opts ...Option) (*Store, error) {
83		if err := os.MkdirAll(dir, 0o700); err != nil {
84			return nil, err
85		}
86		jobs, maxID, err := loadDir(dir)
87		if err != nil {
88			return nil, err
89		}
90		s := &Store{
91			dir:    dir,
92			jobs:   jobs,
93			byID:   make(map[uint64]*storedJob),
94			idem:   make(map[idemIdentity]uint64),
95			nextID: maxID + 1,
96			now:    wallClock{}.Now,
97			waitCh: make(chan struct{}, 1),
98			stopCh: make(chan struct{}),
99		}
100		for _, opt := range opts {
101			opt(s)
102		}
103		for _, j := range jobs {
104			s.byID[j.id] = j
105			if j.requestID != "" {
106				s.idem[idemIdentity{j.submitter, j.requestID}] = j.id
107			}
108		}
109		// 重建失败/取消作业对排队下游的阻断。
110		s.cascadeLocked()
111		s.wg.Add(1)
112		go s.worker()
113		return s, nil
114	}
115	
116	// Close 关闭归档。正在运行的作业会尽快中止并标记为失败（计算被中断），
117	// 排队作业原样保留在磁盘上，下次 [Open] 继续。
118	//
119	// 多次 Close（含并发调用）共同完成对同一个归档对象的一次关闭：每个调用都
120	// 等到 worker 退出、运行中作业的中断处理已经落盘后才成功返回。后发调用
121	// 不能只因为前一次调用已把关闭标记置位就提前返回——否则调用方可能据此立即
122	// 重新打开目录，而旧 worker 仍在补写运行作业的结果。归档完全关闭后的再次
123	// Close 立即成功返回；空闲归档（无运行中作业）也直接完成关闭。
124	func (s *Store) Close() error {
125		s.mu.Lock()
126		if s.closed {
127			// 关闭可能正由另一次并发 Close 进行。wg 在 Open 时 +1、worker 退出
128			// 时归零；Wait 允许被多个 goroutine 同时等待，所有调用都在同一次
129			// 关闭真正完成（worker 已退出、再无计算与补写）时才返回。
130			// 已完全关闭时计数早已归零，这里立即成功返回。
131			s.mu.Unlock()
132			s.wg.Wait()
133			return nil
134		}
135		s.closed = true
136		// 停止标记必须与 closed 在同一次持锁中生效：Submit 的拒绝、worker 的
137		// “是否从队列启动新计算”与“是否把刚结束的计算确认为成功”都观察同一把
138		// 锁。若先放开锁再置 stopping，worker 可能在这个窗口内通过循环开头的
139		// 检查并启动排队作业，或把尚未确认保存的计算按成功落盘——调用方已经在
140		// 被 ErrStoreClosed 拒绝，却仍能拿到关闭过程新产生的成功结果。
141		if s.stopping.CompareAndSwap(false, true) {
142			close(s.stopCh)
143		}
144		var running *storedJob
145		if s.runningID != 0 {
146			running = s.byID[s.runningID]
147		}
148		s.mu.Unlock()
149	
150		// 中止正在运行的计算。
151		if running != nil {
152			running.canceled.Store(true)
153		}
154		s.notify()
155		s.wg.Wait()
156		return nil
157	}
158	
159	// Submit 接受一次作业提交。
160	//
161	// 空序列返回 [ErrEmptySequence]；依赖列表结构不合法（单依赖与列表同时启用、
162	// 含零或重复作业号）返回 [ErrInvalidDependency]——这些请求本身的格式错误先于
163	// 幂等判定拒绝，即使复用已接受的请求号也不例外。
164	//
165	// 非空请求号命中同一提交人的已接受请求时，幂等判定先于“引用的上游必须存在”
166	// 校验：内容（整数序列及次序、种子、有序依赖内容）完全一致时返回原作业的
167	// 当前详情且不返回错误，即使其直接上游记录在重开归档后已缺失、原作业已因此
168	// 被改判为失败；内容不一致返回 [ErrIdempotencyConflict]（同时返回原作业视图，
169	// 仍引用缺失上游时在原因中一并指出），原记录保持原样。重复提交不创建新作业、
170	// 不补建缺失上游、不重新排队失败作业、也不改写原始参数或失败记录。
171	//
172	// 未命中已接受请求的新请求（提交人不同、请求号不同或请求号为空）引用不存在
173	// 的依赖时返回 [ErrDependencyNotFound]；上述拒绝都不产生记录，也不占用请求号。
174	// 相同提交人+请求号+内容的重复提交（含并发重复）返回原作业及其当前状态。
175	func (s *Store) Submit(req SubmitRequest) (*Job, error) {
176		s.mu.Lock()
177		defer s.mu.Unlock()
178		if s.closed || s.stopping.Load() {
179			return nil, ErrStoreClosed
180		}
181		if len(req.Values) == 0 {
182			return nil, ErrEmptySequence
183		}
184		// 先校验与上游存在性无关的列表结构（单依赖与列表互斥、零与重复作业号），
185		// 这类拒绝不依赖内存索引，对新请求与幂等重放一视同仁。
186		if err := s.validateDependencyShapeLocked(&req); err != nil {
187			return nil, err
188		}
189		deps := requestDeps(&req)
190		if req.RequestID != "" {
191			key := idemIdentity{req.Submitter, req.RequestID}
192			if origID, ok := s.idem[key]; ok {
193				orig := s.byID[origID]
194				// 幂等重放先于“引用的上游必须存在”的校验：重新打开归档后原作业
195				// 直接上游的记录可能已经缺失，原作业也因此被改判为失败并落盘。
196				// 只要本次提交的整数序列及次序、种子与有序依赖内容和已接受请求
197				// 完全一致（单依赖写法与只含同一作业号的列表等价），就返回原作业
198				// 的当前详情——不重建缺失上游、不重新排队、不补算、不改写记录。
199				if sameContent(orig, &req) {
200					return s.viewLocked(orig), nil
201				}
202				return s.viewLocked(orig),
203					fmt.Errorf("%w：提交人 %q 的请求号 %q 已用于作业 %d，且本次内容与原请求不一致%s，原记录保持原样",
204						ErrIdempotencyConflict, req.Submitter, req.RequestID, origID,
205						s.missingDependencyNoteLocked(deps))
206			}
207		}
208		// 新请求（请求号为空，或该提交人首次使用此请求号）仍要求每个直接上游
209		// 都存在；引用不存在上游的提交被拒绝，不产生记录，也不占用请求号。
210		// 此检查必须位于幂等判定之后：上面的重放/冲突分支可能引用缺失的上游。
211		if err := s.validateDependenciesExistLocked(deps); err != nil {
212			return nil, err
213		}
214	
215		now := s.now().UTC()
216		j := &storedJob{
217			id:           s.nextID,
218			submitter:    req.Submitter,
219			requestID:    req.RequestID,
220			seed:         req.Seed,
221			values:       append([]int64(nil), req.Values...),
222			dependencies: append([]uint64(nil), deps...),
223			queuedAt:     now,
224			status:       StatusQueued,
225		}
226		// 先持久化，接受之后该提交即不可丢失。
227		if err := s.persist(j); err != nil {
228			return nil, err
229		}
230		s.nextID++
231		s.jobs = append(s.jobs, j)
232		s.byID[j.id] = j
233		if req.RequestID != "" {
234			s.idem[idemIdentity{req.Submitter, req.RequestID}] = j.id
235		}
236		// 依赖已失败/取消时，新接受的作业立刻进入失败终态。
237		s.cascadeLocked()
238		s.notifyLocked()
239		return s.viewLocked(j), nil
240	}
241	
242	// requestDeps 规范化一次提交的直接上游作业号列表，与记录、归档共用 deps.go
243	// 中的同一换算：非空 Dependencies 优先（保持次序）；否则单依赖方式退化为只含
244	// 一个作业号的列表；两者皆无则为 nil。调用前须先经
245	// [Store.validateDependencyShapeLocked] 与（新请求路径上的）
246	// [Store.validateDependenciesExistLocked] 校验。
247	func requestDeps(req *SubmitRequest) []uint64 {
248		return normalizeDependencies(req.HasDependency, req.DependencyID, req.Dependencies)
249	}
250	
251	// validateDependencyShapeLocked 在持锁状态下校验提交依赖列表中与上游存在性
252	// 无关的结构问题：
253	//   - 单依赖方式与非空列表同时启用 → 拒绝；
254	//   - 列表含零或重复作业号 → 拒绝（错误指出具体作业号）。
255	//
256	// 该校验先于幂等判定执行：空整数序列、依赖号为零、重复依赖与两种写法
257	// 同时启用都属于请求本身的格式错误，即使提交人+请求号与已接受请求相同
258	// 也仍返回原有的对应拒绝。
259	func (s *Store) validateDependencyShapeLocked(req *SubmitRequest) error {
260		if req.HasDependency && len(req.Dependencies) > 0 {
261			return fmt.Errorf("%w：单依赖方式与依赖列表不能同时启用", ErrInvalidDependency)
262		}
263		deps := requestDeps(req)
264		seen := make(map[uint64]struct{}, len(deps))
265		for _, id := range deps {
266			if id == 0 {
267				return fmt.Errorf("%w：依赖列表包含无效作业号 0", ErrInvalidDependency)
268			}
269			if _, dup := seen[id]; dup {
270				return fmt.Errorf("%w：依赖列表包含重复作业号 %d", ErrInvalidDependency, id)
271			}
272			seen[id] = struct{}{}
273		}
274		return nil
275	}
276	
277	// validateDependenciesExistLocked 校验规范化后的依赖列表只引用当前归档中
278	// 存在的作业。仅适用于幂等判定之后的新请求：已接受请求的重放（或内容
279	// 冲突）即使引用了重开后缺失的上游，也要返回原作业而不是被这里拒绝。
280	//
281	// 任一拒绝都不产生记录，也不占用幂等请求号。
282	func (s *Store) validateDependenciesExistLocked(deps []uint64) error {
283		for _, id := range deps {
284			if s.byID[id] == nil {
285				return fmt.Errorf("%w：作业号 %d", ErrDependencyNotFound, id)
286			}
287		}
288		return nil
289	}
290	
291	// missingDependencyNoteLocked 在幂等冲突时补充说明：若本次（与原请求内容
292	// 不一致的）提交仍引用已经缺失的上游，明确指出缺失的作业号，使冲突原因
293	// 不会被误读成仅仅是上游不存在。
294	func (s *Store) missingDependencyNoteLocked(deps []uint64) string {
295		for _, id := range deps {
296			if s.byID[id] == nil {
297				return fmt.Sprintf("；本次引用的直接上游作业 %d 记录已缺失", id)
298			}
299		}
300		return ""
301	}
302	
303	// sameContent 判断两次提交的内容是否一致；整数次序或依赖列表（内容与次序）
304	// 不同即视为不同内容。单依赖方式与只含同一作业号的列表视为相同内容。
305	func sameContent(j *storedJob, req *SubmitRequest) bool {
306		if j.seed != req.Seed {
307			return false
308		}
309		rd := requestDeps(req)
310		if len(j.dependencies) != len(rd) {
311			return false
312		}
313		for i := range j.dependencies {
314			if j.dependencies[i] != rd[i] {
315				return false
316			}
317		}
318		if len(j.values) != len(req.Values) {
319			return false
320		}
321		for i := range j.values {
322			if j.values[i] != req.Values[i] {
323				return false
324			}
325		}
326		return true
327	}
328	
329	// Get 按作业号读取作业详情（含成功归档）；不存在返回 [ErrNotFound]。
330	func (s *Store) Get(id uint64) (*Job, error) {
331		s.mu.Lock()
332		defer s.mu.Unlock()
333		j := s.byID[id]
334		if j == nil {
335			return nil, fmt.Errorf("%w：作业号 %d", ErrNotFound, id)
336		}
337		return s.viewLocked(j), nil
338	}
339	
340	// Cancel 请求取消作业。
341	//
342	// 排队或运行中的作业都可以取消；取消以“取消状态已成功保存进归档记录”为生效
343	// 条件：只有原子替换原记录成功后，返回结果、可查询状态与磁盘记录才一致地呈现
344	// 为取消，该作业及依赖它的作业才不会再产生成功归档。若取消记录无法创建临时
345	// 文件或无法替换原记录，返回的是实际保存错误，作业保持原状——不新增完成时间、
346	// 不清空原有信息、不中止正在运行的计算、不级联标记下游，排队与调度规则不变；
347	// 写入条件恢复后对仍处于排队或运行状态的同一作业再次取消会重新尝试保存。
348	// 重复取消已取消的作业仍返回成功；对已成功或已失败的作业取消返回
349	// [ErrNotCancellable]，原结果保持不变（计算在两次取消请求之间完成时亦然）。
350	func (s *Store) Cancel(id uint64) (*Job, error) {
351		s.mu.Lock()
352		defer s.mu.Unlock()
353		if s.closed {
354			return nil, ErrStoreClosed
355		}
356		j := s.byID[id]
357		if j == nil {
358			return nil, fmt.Errorf("%w：作业号 %d", ErrNotFound, id)
359		}
360		switch j.status {
361		case StatusCanceled:
362			return s.viewLocked(j), nil
363		case StatusSucceeded, StatusFailed:
364			return s.viewLocked(j),
365				fmt.Errorf("%w：作业 %d 当前状态为 %s", ErrNotCancellable, id, j.status)
366		}
367	
368		// queued / running：先把取消终态写入原记录，确认原子替换成功后才让取消
369		// 生效。持锁期间外界观察不到中间态；若创建临时记录或替换原记录失败，
370		// 必须逐字段回滚，内存与磁盘都保持取消前的原状并返回实际保存错误，
371		// 不能把这次取消当作已完成。
372		now := s.now().UTC()
373		prevStatus := j.status
374		prevFinishedAt := j.finishedAt
375		prevReason := j.failureReason
376		prevBlocker := j.blockerID
377		prevEffective := j.effectiveValues
378		prevArchive := j.archive
379		j.status = StatusCanceled
380		j.failureReason = ""
381		j.blockerID = 0
382		if j.finishedAt.IsZero() {
383			j.finishedAt = now
384		}
385		j.effectiveValues = nil
386		j.archive = nil
387		if err := s.persist(j); err != nil {
388			j.status = prevStatus
389			j.finishedAt = prevFinishedAt
390			j.failureReason = prevReason
391			j.blockerID = prevBlocker
392			j.effectiveValues = prevEffective
393			j.archive = prevArchive
394			return nil, err
395		}
396	
397		// 取消已确认保存：提交终态，让正在运行的计算尽快中止，并级联标记下游。
398		j.canceled.Store(true)
399		// 依赖它的等待者一并失败，且继续向更下游传播。
400		s.cascadeLocked()
401		s.notifyLocked()
402		return s.viewLocked(j), nil
403	}
404	
405	// List 按提交人和提交时间范围（两端均包含）列出记录，结果按提交先后排列。
406	// start 晚于 end 返回 [ErrInvalidTimeRange]。零值时间表示该端不限。
407	func (s *Store) List(submitter string, start, end time.Time) ([]*Job, error) {
408		s.mu.Lock()
409		defer s.mu.Unlock()
410		if !start.IsZero() && !end.IsZero() && start.After(end) {
411			return nil, fmt.Errorf("%w：起始时间 %s 晚于结束时间 %s",
412				ErrInvalidTimeRange, start.Format(time.RFC3339Nano), end.Format(time.RFC3339Nano))
413		}
414		out := make([]*Job, 0)
415		for _, j := range s.jobs { // jobs 已按 id 升序，即提交先后
416			if j.submitter != submitter {
417				continue
418			}
419			if !start.IsZero() && j.queuedAt.Before(start) {
420				continue
421			}
422			if !end.IsZero() && j.queuedAt.After(end) {
423				continue
424			}
425			out = append(out, s.viewLocked(j))
426		}
427		return out, nil
428	}
429	
430	// cascadeLocked 把“直接上游已失败/取消”的排队作业标记为失败并递归传播。
431	//
432	// 上游在提交时必须已存在，因此上游作业号必然更小，按作业号升序单趟
433	// 扫描即可让阻断沿链条传播到最下游。选择直接阻断者、确定根因与构造失败
434	// 原因统一走 blocker.go 中的规则（与重开归档同一套）：作业有多个直接上游时
435	// 按保存的依赖顺序选取最靠前的已失败/取消者，根因沿该上游已有的阻断信息
436	// 保留；作业一旦失败，其原因不再被后来发生的上游状态变化改写。
437	func (s *Store) cascadeLocked() {
438		for _, j := range s.jobs {
439			if j.status != StatusQueued || len(j.dependencies) == 0 {
440				continue
441			}
442			directID, direct, blocked := pickBlockingUpstream(j, s.byID, runtimeUpstreamBlocked)
443			if !blocked {
444				continue
445			}
446			root := blockerRoot(direct, directID)
447			s.markFailedLocked(j, blockedFailureReason(runtimeBlockedHead(direct), direct, directID, root), root)
448		}
449	}
450	
451	// pickRunnableLocked 返回提交顺序上第一个可运行的排队作业。
452	// 可运行要求全部直接上游都已成功并归档；只要还有一个上游在排队或运行，
453	// 该作业就被跳过，不挡住后面可运行的作业。
454	func (s *Store) pickRunnableLocked() *storedJob {
455		for _, j := range s.jobs {
456			if j.status != StatusQueued {
457				continue
458			}
459			if len(j.dependencies) == 0 {
460				return j
461			}
462			ready := true
463			for _, id := range j.dependencies {
464				dep := s.byID[id]
465				if dep == nil || dep.status != StatusSucceeded {
466					ready = false
467					break
468				}
469			}
470			if ready {
471				return j
472			}
473		}
474		return nil
475	}
476	
477	// notifyLocked 在持锁状态下非阻塞唤醒 worker。
478	func (s *Store) notifyLocked() {
479		select {
480		case s.waitCh <- struct{}{}:
481		default:
482		}
483	}
484	
485	// notify 在不持锁时唤醒 worker。
486	func (s *Store) notify() {
487		s.mu.Lock()
488		s.notifyLocked()
489		s.mu.Unlock()
490	}
491	
492	// persistRetry 对落盘做有限次重试，尽量避免内存状态与磁盘记录分叉。
493	func (s *Store) persistRetry(j *storedJob, attempts int) error {
494		var err error
495		for i := 0; i < attempts; i++ {
496			if err = s.persist(j); err == nil {
497				return nil
498			}
499		}
500		return err
501	}
502	
503	// worker 是本地唯一的计算执行体。
504	func (s *Store) worker() {
505		defer s.wg.Done()
506		for {
507			s.mu.Lock()
508			if s.stopping.Load() {
509				s.mu.Unlock()
510				return
511			}
512			j := s.pickRunnableLocked()
513			if j == nil {
514				ch := s.waitCh
515				s.mu.Unlock()
516				select {
517				case <-ch:
518				case <-s.stopCh:
519				}
520				continue
521			}
522	
523			// 进入运行并原子持久化该状态。
524			j.status = StatusRunning
525			j.startedAt = s.now().UTC()
526			// 实际输入 = 原始序列 + 各直接上游的总和（严格按列表顺序追加）。
527			inputs := append([]int64(nil), j.values...)
528			for _, id := range j.dependencies {
529				if dep := s.byID[id]; dep != nil && dep.archive != nil {
530					inputs = append(inputs, dep.archive.Sum)
531				}
532			}
533			seed := j.seed
534			s.runningID = j.id
535			if err := s.persistRetry(j, 3); err != nil {
536				// 连运行状态都无法落盘：保守地失败，不进行计算。
537				s.markFailedLocked(j, "无法持久化作业状态："+err.Error(), 0)
538				s.runningID = 0
539				s.cascadeLocked()
540				s.notifyLocked()
541				s.mu.Unlock()
542				continue
543			}
544			s.mu.Unlock()
545	
546			abort := func() bool { return j.canceled.Load() || s.stopping.Load() }
547			doCompute := s.compute
548			if doCompute == nil {
549				doCompute = func(_ uint64, in []int64, sd int64, c func() bool) (int64, int64, string, bool) {
550					return computeResult(in, sd, c)
551				}
552			}
553			sum, sumSq, reason, ok := doCompute(j.id, inputs, seed, abort)
554	
555			s.mu.Lock()
556			s.runningID = 0
557			switch {
558			case j.status == StatusCanceled:
559				// 用户取消已在 Cancel 中落盘；此处确保丢弃任何计算产物。
560				j.archive = nil
561				j.effectiveValues = nil
562				_ = s.persistRetry(j, 3)
563				s.cascadeLocked()
564			case s.stopping.Load():
565				s.markFailedLocked(j, "计算被中断：归档在计算过程中关闭", 0)
566				s.cascadeLocked()
567			case !ok:
568				s.markFailedLocked(j, reason, 0)
569				s.cascadeLocked()
570			default:
571				// 成功：状态与完整归档在同一条记录的同一次原子写入中可见。
572				completed := s.now().UTC()
573				a := newArchive(j, inputs, sum, sumSq, completed)
574				j.effectiveValues = append([]int64(nil), inputs...)
575				j.status = StatusSucceeded
576				j.finishedAt = completed
577				j.failureReason = ""
578				j.blockerID = 0
579				j.archive = a
580				if err := s.persistRetry(j, 3); err != nil {
581					// 落盘失败时绝不让对外可见“成功却没有归档”：回退为失败。
582					j.archive = nil
583					j.effectiveValues = nil
584					s.markFailedLocked(j, "结果归档写入失败："+err.Error(), 0)
585					// 归档写入失败与计算溢出等失败同等对待：立即沿依赖链阻断所有仍在
586					// 排队等待它的作业，使等待者无需等到下一次提交/取消即进入失败终态。
587					s.cascadeLocked()
588				}
589			}
590			s.notifyLocked()
591			s.mu.Unlock()
592		}
593	}
594	
595	// markFailedLocked 在持锁状态下把作业置为失败终态并尝试落盘。
596	func (s *Store) markFailedLocked(j *storedJob, reason string, blocker uint64) {
597		j.status = StatusFailed
598		j.failureReason = reason
599		j.blockerID = blocker
600		if j.finishedAt.IsZero() {
601			j.finishedAt = s.now().UTC()
602		}
603		j.archive = nil
604		j.effectiveValues = nil
605		_ = s.persistRetry(j, 3)
606	}
607	
608	// newArchive 构造成功归档；CompletedAt 之外的全部字段都是确定性的。
609	// 上游作业号只作记录，不参与任何摘要与校验值。
610	func newArchive(j *storedJob, effective []int64, sum, sumSquares int64, completedAt time.Time) *Archive {
611		inDigest := inputsDigestHex(effective, j.seed)
612		resDigest := resultDigestHex(effective, j.seed, sum, sumSquares)
613		log := buildLog(effective, j.seed, sum, sumSquares)
614		checksum := checksumHex(effective, j.seed, sum, sumSquares, log, resDigest)
615		hasDependency, dependencyID := legacyDependencyFields(j.dependencies)
616		return &Archive{
617			JobID:           j.id,
618			Submitter:       j.submitter,
619			RequestID:       j.requestID,
620			IdentityRaw:     rawIdentity(j.submitter, j.requestID),
621			Seed:            j.seed,
622			Values:          append([]int64(nil), j.values...),
623			HasDependency:   hasDependency,
624			DependencyID:    dependencyID,
625			Dependencies:    append([]uint64(nil), j.dependencies...),
626			EffectiveValues: append([]int64(nil), effective...),
627			InputsDigest:    inDigest,
628			Sum:             sum,
629			SumOfSquares:    sumSquares,
630			ResultDigest:    resDigest,
631			Log:             log,
632			Checksum:        checksum,
633			CompletedAt:     completedAt,
634		}
635	}
636	
637	// viewLocked 在持锁状态下生成对外只读视图，全部切片深拷贝。
638	func (s *Store) viewLocked(j *storedJob) *Job {
639		v := &Job{
640			ID:              j.id,
641			Submitter:       j.submitter,
642			RequestID:       j.requestID,
643			Seed:            j.seed,
644			Values:          append([]int64(nil), j.values...),
645			Dependencies:    append([]uint64(nil), j.dependencies...),
646			QueuedAt:        j.queuedAt,
647			StartedAt:       j.startedAt,
648			FinishedAt:      j.finishedAt,
649			Status:          j.status,
650			FailureReason:   j.failureReason,
651			BlockerID:       j.blockerID,
652			EffectiveValues: append([]int64(nil), j.effectiveValues...),
653		}
654		v.HasDependency, v.DependencyID = legacyDependencyFields(j.dependencies)
655		if j.status == StatusQueued {
656			v.WaitReason = WaitSlot
657			// 列出尚未成功归档的直接上游，保持提交时的顺序。
658			for _, id := range j.dependencies {
659				if dep := s.byID[id]; dep == nil || dep.status != StatusSucceeded {
660					v.PendingDependencies = append(v.PendingDependencies, id)
661				}
662			}
663			if len(v.PendingDependencies) > 0 {
664				v.WaitReason = WaitDependency
665			}
666		}
667		if j.archive != nil {
668			a := *j.archive
669			a.Values = append([]int64(nil), j.archive.Values...)
670			a.EffectiveValues = append([]int64(nil), j.archive.EffectiveValues...)
671			a.Dependencies = append([]uint64(nil), j.archive.Dependencies...)
672			if j.archive.IdentityRaw != nil {
673				raw := *j.archive.IdentityRaw
674				a.IdentityRaw = &raw
675			}
676			v.Archive = &a
677		}
678		return v
679	}
680	
681	// Dir 返回归档目录路径。
682	func (s *Store) Dir() string { return s.dir }
683

