162		base := time.Date(2026, 4, 3, 8, 0, 0, 0, time.UTC)
163		names := []string{
164			jobFileName(11),
165			"job-00000000000000000011-a.json",
166			"job-00000000000000000011-b.json",
167		}
168		for i, name := range names {
169			writeNamedSyntheticRecord(t, dir, name,
170				queuedStoredJob(11, "u", []int64{int64(i + 1)}, base.Add(time.Duration(i)*time.Second)))
171		}
172		s, err := Open(dir)
173		if err == nil {
174			if s != nil {
175				_ = s.Close()
176			}
177			t.Fatal("三份同号记录必须拒绝打开")
178		}
179		if s != nil {
180			t.Fatalf("冲突时归档对象必须为 nil: %#v", s)
181		}
182		named := 0
183		for _, name := range names {
184			if strings.Contains(err.Error(), name) {
185				named++
186			}
187		}
188		if named < 2 {
189			t.Fatalf("错误至少要包含两份冲突记录的文件名，实际包含 %d 份: %v", named, err)
190		}
191	}
192	
193	// TestOpenDuplicateJobIDDoesNotTouchAnyRecord 存在冲突时，本次打开不能启动
194	// 任何计算，也不能按正常恢复规则把其他作业改判失败或补写结果：中断的运行
195	// 记录、排队下游、成功归档（含完成时间与校验值）、已失败记录以及冲突记录
196	// 自身的文件字节必须全部保持原样，且与它们是否比冲突记录更早被读取无关。
197	func TestOpenDuplicateJobIDDoesNotTouchAnyRecord(t *testing.T) {
198		base := time.Date(2026, 4, 4, 8, 0, 0, 0, time.UTC)
199	
200		cases := []struct {
201			name    string
202			dupName string // 冲突额外文件的命名位置：排在标准文件名之前或之后
203			setup   func(t *testing.T, dir string)
204		}{
205			{
206				name:    "冲突记录排在其他记录之后",
207				dupName: "job-00000000000000000005-dup.json",
208			},
209			{
210				name:    "冲突记录排在其他记录之前",
211				dupName: "job--0000000000000000005-dup.json",
212			},
213		}
214		for _, tc := range cases {
215			t.Run(tc.name, func(t *testing.T) {
216				dir := t.TempDir()
217				// 作业 1：上次中断的运行记录，正常恢复规则会改判失败并补完成时间。
218				writeSyntheticRecord(t, dir, &storedJob{
219					id: 1, submitter: "a", values: []int64{1, 2},
220					queuedAt: base, startedAt: base.Add(time.Second), status: StatusRunning,
221				})
222				// 作业 2：排队等待作业 1，正常恢复会级联失败。
223				writeSyntheticRecord(t, dir,
224					queuedStoredJob(2, "a", []int64{3}, base.Add(2*time.Second), 1))
225				// 作业 3：合法成功归档，正常情况下摘要与校验值原样保留。
226				writeSyntheticRecord(t, dir,
227					succeededStoredJob(t, 3, []int64{4}, base.Add(3*time.Second), base.Add(4*time.Second)))
228				// 作业 4：已失败终态记录，正常恢复不改动。
229				writeSyntheticRecord(t, dir, &storedJob{
230					id: 4, submitter: "a", values: []int64{5},
231					queuedAt: base.Add(5 * time.Second), finishedAt: base.Add(6 * time.Second),
232					status: StatusFailed, failureReason: "平方和超出 int64 范围",
233				})
234				// 作业 5 同号两份：一份排队，一份带完整成功归档。文件名不同不能
235				// 让它们成为两个作业，也不能挑带完整结果的那份继续。
236				writeSyntheticRecord(t, dir,
237					queuedStoredJob(5, "a", []int64{9}, base.Add(7*time.Second)))
238				writeNamedSyntheticRecord(t, dir, tc.dupName,
239					succeededStoredJob(t, 5, []int64{9}, base.Add(7*time.Second), base.Add(8*time.Second)))
240	
241				before := snapshotDir(t, dir)
242				s, err := Open(dir)
243				if err == nil {
244					if s != nil {
245						_ = s.Close()
246					}
247					t.Fatal("存在重复作业号时必须打开失败")
248				}
249				if s != nil {
250					t.Fatalf("冲突时归档对象必须为 nil: %#v", s)
251				}
252				assertDirUnchanged(t, dir, before)
253	
254				// 没有任何延迟补写：稍等后再次比对，所有记录（含状态、完成时间、
255				// 归档与校验值）仍是打开前的字节。
256				time.Sleep(50 * time.Millisecond)
257				assertDirUnchanged(t, dir, before)
258			})
259		}
260	}
261	
262	// TestOpenDuplicateJobIDRunningPairNotFailed 重复作业号的两份记录中一份是
263	// running 时，也不能先按“计算被中断”改判它再返回重复错误。
264	func TestOpenDuplicateJobIDRunningPairNotFailed(t *testing.T) {
265		dir := t.TempDir()
266		base := time.Date(2026, 4, 5, 8, 0, 0, 0, time.UTC)
267		writeSyntheticRecord(t, dir, &storedJob{
268			id: 6, submitter: "a", values: []int64{1},
269			queuedAt: base, startedAt: base.Add(time.Second), status: StatusRunning,
270		})
271		writeNamedSyntheticRecord(t, dir, "job-00000000000000000006-dup.json",
272			queuedStoredJob(6, "b", []int64{2}, base.Add(2*time.Second)))
273		before := snapshotDir(t, dir)
274	
275		s, err := Open(dir)
276		if err == nil {
277			if s != nil {
278				_ = s.Close()
279			}
280			t.Fatal("running 与排队记录同号也必须拒绝打开")
281		}
282		if s != nil {
283			t.Fatalf("冲突时归档对象必须为 nil: %#v", s)
284		}
285		assertDirUnchanged(t, dir, before)
286	}
287	
288	// TestOpenDistinctJobIDsWithSameContentAccepted 不同作业号即使整数序列、种子
289	// 或结果完全相同，仍是不同作业，不因这项检查被拒绝；已保存作业号保持不变，
290	// 正常查询与幂等重放继续可用。
291	func TestOpenDistinctJobIDsWithSameContentAccepted(t *testing.T) {
292		dir := t.TempDir()
293		base := time.Date(2026, 4, 6, 8, 0, 0, 0, time.UTC)
294		// 同提交人、同请求号、同内容但作业号不同在正常提交中不会发生，因此这里
295		// 请求号留空；两份记录除作业号与提交时间外完全一致。
296		writeSyntheticRecord(t, dir,
297			queuedStoredJob(1, "alice", []int64{1, 2, 3}, base))
298		writeSyntheticRecord(t, dir,
299			queuedStoredJob(2, "alice", []int64{1, 2, 3}, base.Add(time.Second)))
300	
301		s, err := Open(dir)
302		if err != nil {
303			t.Fatalf("不同作业号同内容不应被拒绝: %v", err)
304		}
305		defer s.Close()
306		j1 := waitStatus(t, s, 1, StatusSucceeded)
307		j2 := waitStatus(t, s, 2, StatusSucceeded)
308		if j1.Archive.Sum != j2.Archive.Sum || j1.Archive.Checksum != j2.Archive.Checksum {
309			t.Fatal("同输入同种子的结果摘要与校验值本应一致")
310		}
311		replay, err := s.Submit(SubmitRequest{
312			Submitter: "alice", RequestID: "later", Values: []int64{7},
313		})
314		if err != nil {
315			t.Fatalf("冲突解决后的新提交必须可用: %v", err)
316		}
317		waitStatus(t, s, replay.ID, StatusSucceeded)
318		if replay.ID <= 2 {
319			t.Fatalf("新作业号必须续号分配，得到 %d", replay.ID)
320		}
321	}
322	
323	// TestOpenAfterDuplicateResolvedRecoversNormally 调用方处理冲突（删除一份）
324	// 后再次打开，既有恢复规则照常生效：running 改判失败并级联排队下游，
325	// 成功归档保留，留下的那份同号记录正常参与调度。
326	func TestOpenAfterDuplicateResolvedRecoversNormally(t *testing.T) {
327		dir := t.TempDir()
328		base := time.Date(2026, 4, 7, 8, 0, 0, 0, time.UTC)
329		writeSyntheticRecord(t, dir, &storedJob{
330			id: 1, submitter: "a", values: []int64{1, 2},
331			queuedAt: base, startedAt: base.Add(time.Second), status: StatusRunning,
332		})
333		writeSyntheticRecord(t, dir,
334			queuedStoredJob(2, "a", []int64{3}, base.Add(2*time.Second), 1))
335		succeeded := succeededStoredJob(t, 3, []int64{4}, base.Add(3*time.Second), base.Add(4*time.Second))
336		wantChecksum := succeeded.archive.Checksum
337		writeSyntheticRecord(t, dir, succeeded)
338		writeSyntheticRecord(t, dir,
339			queuedStoredJob(5, "a", []int64{9}, base.Add(7*time.Second)))
340		dupName := "job-00000000000000000005-dup.json"
341		writeNamedSyntheticRecord(t, dir, dupName,
342			queuedStoredJob(5, "b", []int64{10}, base.Add(8*time.Second)))
343	
344		if s, err := Open(dir); err == nil {
345			_ = s.Close()
346			t.Fatal("处理冲突前打开必须失败")
347		}
348		// 调用方自行删除一份冲突记录。
349		if err := os.Remove(filepath.Join(dir, dupName)); err != nil {
350			t.Fatal(err)
351		}
352	
353		s, err := Open(dir)
354		if err != nil {
355			t.Fatalf("冲突解决后再次打开应按既有规则恢复: %v", err)
356		}
357		defer s.Close()
358	
359		j1, _ := s.Get(1)
360		if j1.Status != StatusFailed || !strings.Contains(j1.FailureReason, "中断") {
361			t.Fatalf("作业 1 应按既有规则改判中断失败: %s %q", j1.Status, j1.FailureReason)
362		}
363		j2 := waitStatus(t, s, 2, StatusFailed)
364		if j2.BlockerID != 1 {
365			t.Fatalf("作业 2 应沿链条保留根因 1，得到 %d", j2.BlockerID)
366		}
367		j3, _ := s.Get(3)
368		if j3.Status != StatusSucceeded || j3.Archive == nil || j3.Archive.Checksum != wantChecksum {
369			t.Fatalf("合法成功归档应原样保留: %+v", j3)
370		}
371		j5 := waitStatus(t, s, 5, StatusSucceeded)
372		if j5.Archive == nil || j5.Archive.Sum != 9 {
373			t.Fatalf("保留的作业 5 应正常计算完成: %+v", j5)
374		}
375	}
376	
377	// TestOpenDuplicateDoesNotMaskPreexistingRecordErrors 原有的解析失败、版本
378	// 不支持与非法状态错误继续有效；与重复作业号并存时，按目录读取顺序先遇到
379	// 的记录返回对应的原有错误。
380	func TestOpenDuplicateDoesNotMaskPreexistingRecordErrors(t *testing.T) {
381		base := time.Date(2026, 4, 8, 8, 0, 0, 0, time.UTC)
382	
383		t.Run("损坏记录单独存在", func(t *testing.T) {
384			dir := t.TempDir()
385			writeNamedSyntheticRecord(t, dir, jobFileName(1),
386				queuedStoredJob(1, "a", []int64{1}, base))
387			if err := os.WriteFile(filepath.Join(dir, "job-00000000000000000002.json"),
388				[]byte("{not json"), 0o600); err != nil {
389				t.Fatal(err)
390			}
391			s, err := Open(dir)
392			if err == nil {
393				_ = s.Close()
394				t.Fatal("损坏记录必须导致打开失败")
395			}
396			if s != nil || !strings.Contains(err.Error(), "损坏") {
397				t.Fatalf("应返回原有的记录损坏错误且归档为 nil: %v", err)
398			}
399		})
400	
401		t.Run("版本不支持", func(t *testing.T) {
402			dir := t.TempDir()
403			writeNamedSyntheticRecord(t, dir, jobFileName(1),
404				queuedStoredJob(1, "a", []int64{1}, base))
405			writeRawJSONRecord(t, dir, 2, `{
406	  "version": "numeric-job-v9",
407	  "id": 2,
408	  "submitter": "a",
409	  "request_id": "",
410	  "seed": 0,
411	  "values": [1],
412	  "has_dependency": false,
413	  "dependency_id": 0,
414	  "queued_at": "2026-04-08T08:00:00Z",
415	  "status": "queued"
416	}`)
417			s, err := Open(dir)
418			if err == nil {
419				_ = s.Close()
420				t.Fatal("版本不支持必须导致打开失败")
421			}
422			if s != nil || !strings.Contains(err.Error(), "版本不受支持") {
423				t.Fatalf("应返回原有的版本不支持错误且归档为 nil: %v", err)
424			}
425		})
426	
427		t.Run("非法状态", func(t *testing.T) {
428			dir := t.TempDir()
429			writeNamedSyntheticRecord(t, dir, jobFileName(1),
430				queuedStoredJob(1, "a", []int64{1}, base))
431			writeRawJSONRecord(t, dir, 2, `{
432	  "version": "numeric-job-v1",
433	  "id": 2,
434	  "submitter": "a",
435	  "request_id": "",
436	  "seed": 0,
437	  "values": [1],
438	  "has_dependency": false,
439	  "dependency_id": 0,
440	  "queued_at": "2026-04-08T08:00:00Z",
441	  "status": "paused"
442	}`)
443			s, err := Open(dir)
444			if err == nil {
445				_ = s.Close()
446				t.Fatal("非法状态必须导致打开失败")
447			}
448			if s != nil || !strings.Contains(err.Error(), "状态非法") {
449				t.Fatalf("应返回原有的非法状态错误且归档为 nil: %v", err)
450			}
451		})
452	
453		t.Run("损坏记录排在冲突之前时先报损坏", func(t *testing.T) {
454			dir := t.TempDir()
455			// job-...01.json 损坏，文件名排序早于作业 3 的冲突对。
456			if err := os.WriteFile(filepath.Join(dir, jobFileName(1)),
457				[]byte("{not json"), 0o600); err != nil {
458				t.Fatal(err)
459			}
460			writeNamedSyntheticRecord(t, dir, jobFileName(3),
461				queuedStoredJob(3, "a", []int64{1}, base))
462			writeNamedSyntheticRecord(t, dir, "job-00000000000000000003-dup.json",
463				queuedStoredJob(3, "b", []int64{2}, base))
464			s, err := Open(dir)
465			if err == nil {
466				_ = s.Close()
467				t.Fatal("必须打开失败")
468			}
469			if s != nil || !strings.Contains(err.Error(), "损坏") {
470				t.Fatalf("先读到损坏记录时应保留原有损坏错误: %v", err)
471			}
472		})
473	
474		t.Run("同目录另有损坏记录时保留原有损坏错误", func(t *testing.T) {
475			// 重复作业号检查只在全部记录都可正常解析、版本及状态合法时生效；
476			// 损坏记录即使文件名排在冲突对之后，其原有打开错误仍然有效。
477			dir := t.TempDir()
478			writeNamedSyntheticRecord(t, dir, "job-00000000000000000001-a.json",
479				queuedStoredJob(1, "a", []int64{1}, base))
480			writeNamedSyntheticRecord(t, dir, jobFileName(1),
481				queuedStoredJob(1, "b", []int64{2}, base))
482			if err := os.WriteFile(filepath.Join(dir, jobFileName(2)),
483				[]byte("{not json"), 0o600); err != nil {
484				t.Fatal(err)
485			}
486			before := snapshotDir(t, dir)
487			s, err := Open(dir)
488			if err == nil {
489				_ = s.Close()
490				t.Fatal("必须打开失败")
491			}
492			if s != nil || !strings.Contains(err.Error(), "损坏") {
493				t.Fatalf("存在损坏记录时应保留原有的损坏错误，而非重复作业号错误: %v", err)
494			}
495			// 解析阶段失败同样不允许改写目录内任何记录。
496			assertDirUnchanged(t, dir, before)
497		})
498	}
