// TestOpenDistinctJobIDsWithSameContentAccepted 不同作业号即使整数序列、种子
// 或结果完全相同，仍是不同作业，不因这项检查被拒绝；已保存作业号保持不变，
// 正常查询与幂等重放继续可用。
func TestOpenDistinctJobIDsWithSameContentAccepted(t *testing.T) {
	dir := t.TempDir()
	base := time.Date(2026, 4, 6, 8, 0, 0, 0, time.UTC)
	// 同提交人、同请求号、同内容但作业号不同在正常提交中不会发生，因此这里
	// 请求号留空；两份记录除作业号与提交时间外完全一致。
	writeSyntheticRecord(t, dir,
		queuedStoredJob(1, "alice", []int64{1, 2, 3}, base))
	writeSyntheticRecord(t, dir,
		queuedStoredJob(2, "alice", []int64{1, 2, 3}, base.Add(time.Second)))

	s, err := Open(dir)
	if err != nil {
		t.Fatalf("不同作业号同内容不应被拒绝: %v", err)
	}
	defer s.Close()
	j1 := waitStatus(t, s, 1, StatusSucceeded)
	j2 := waitStatus(t, s, 2, StatusSucceeded)
	if j1.Archive.Sum != j2.Archive.Sum || j1.Archive.Checksum != j2.Archive.Checksum {
		t.Fatal("同输入同种子的结果摘要与校验值本应一致")
	}
	replay, err := s.Submit(SubmitRequest{
		Submitter: "alice", RequestID: "later", Values: []int64{7},
	})
	if err != nil {
		t.Fatalf("冲突解决后的新提交必须可用: %v", err)
	}
	waitStatus(t, s, replay.ID, StatusSucceeded)
	if replay.ID <= 2 {
		t.Fatalf("新作业号必须续号分配，得到 %d", replay.ID)
	}
}

// TestOpenAfterDuplicateResolvedRecoversNormally 调用方处理冲突（删除一份）
// 后再次打开，既有恢复规则照常生效：running 改判失败并级联排队下游，
// 成功归档保留，留下的那份同号记录正常参与调度。
func TestOpenAfterDuplicateResolvedRecoversNormally(t *testing.T) {
	dir := t.TempDir()
	base := time.Date(2026, 4, 7, 8, 0, 0, 0, time.UTC)
	writeSyntheticRecord(t, dir, &storedJob{
		id: 1, submitter: "a", values: []int64{1, 2},
		queuedAt: base, startedAt: base.Add(time.Second), status: StatusRunning,
	})
	writeSyntheticRecord(t, dir,
		queuedStoredJob(2, "a", []int64{3}, base.Add(2*time.Second), 1))
	succeeded := succeededStoredJob(t, 3, []int64{4}, base.Add(3*time.Second), base.Add(4*time.Second))
	wantChecksum := succeeded.archive.Checksum
	writeSyntheticRecord(t, dir, succeeded)
	writeSyntheticRecord(t, dir,
		queuedStoredJob(5, "a", []int64{9}, base.Add(7*time.Second)))
	dupName := "job-00000000000000000005-dup.json"
	writeNamedSyntheticRecord(t, dir, dupName,
		queuedStoredJob(5, "b", []int64{10}, base.Add(8*time.Second)))

	if s, err := Open(dir); err == nil {
		_ = s.Close()
		t.Fatal("处理冲突前打开必须失败")
	}
	// 调用方自行删除一份冲突记录。
	if err := os.Remove(filepath.Join(dir, dupName)); err != nil {
		t.Fatal(err)
	}

	s, err := Open(dir)
	if err != nil {
		t.Fatalf("冲突解决后再次打开应按既有规则恢复: %v", err)
	}
	defer s.Close()

	j1, _ := s.Get(1)
	if j1.Status != StatusFailed || !strings.Contains(j1.FailureReason, "中断") {
		t.Fatalf("作业 1 应按既有规则改判中断失败: %s %q", j1.Status, j1.FailureReason)
	}
	j2 := waitStatus(t, s, 2, StatusFailed)
	if j2.BlockerID != 1 {
		t.Fatalf("作业 2 应沿链条保留根因 1，得到 %d", j2.BlockerID)
	}
	j3, _ := s.Get(3)
	if j3.Status != StatusSucceeded || j3.Archive == nil || j3.Archive.Checksum != wantChecksum {
		t.Fatalf("合法成功归档应原样保留: %+v", j3)
	}
	j5 := waitStatus(t, s, 5, StatusSucceeded)
	if j5.Archive == nil || j5.Archive.Sum != 9 {
		t.Fatalf("保留的作业 5 应正常计算完成: %+v", j5)
	}
}

// TestOpenDuplicateDoesNotMaskPreexistingRecordErrors 原有的解析失败、版本
// 不支持与非法状态错误继续有效；与重复作业号并存时，按目录读取顺序先遇到
// 的记录返回对应的原有错误。
func TestOpenDuplicateDoesNotMaskPreexistingRecordErrors(t *testing.T) {
	base := time.Date(2026, 4, 8, 8, 0, 0, 0, time.UTC)

	t.Run("损坏记录单独存在", func(t *testing.T) {
		dir := t.TempDir()
		writeNamedSyntheticRecord(t, dir, jobFileName(1),
			queuedStoredJob(1, "a", []int64{1}, base))
		if err := os.WriteFile(filepath.Join(dir, "job-00000000000000000002.json"),
			[]byte("{not json"), 0o600); err != nil {
			t.Fatal(err)
		}
		s, err := Open(dir)
		if err == nil {
			_ = s.Close()
			t.Fatal("损坏记录必须导致打开失败")
		}
		if s != nil || !strings.Contains(err.Error(), "损坏") {
			t.Fatalf("应返回原有的记录损坏错误且归档为 nil: %v", err)
		}
	})

	t.Run("版本不支持", func(t *testing.T) {
		dir := t.TempDir()
		writeNamedSyntheticRecord(t, dir, jobFileName(1),
			queuedStoredJob(1, "a", []int64{1}, base))
		writeRawJSONRecord(t, dir, 2, `{
  "version": "numeric-job-v9",
  "id": 2,
  "submitter": "a",
  "request_id": "",
  "seed": 0,
  "values": [1],
  "has_dependency": false,
  "dependency_id": 0,
  "queued_at": "2026-04-08T08:00:00Z",
  "status": "queued"
}`)
		s, err := Open(dir)
		if err == nil {
			_ = s.Close()
			t.Fatal("版本不支持必须导致打开失败")
		}
		if s != nil || !strings.Contains(err.Error(), "版本不受支持") {
			t.Fatalf("应返回原有的版本不支持错误且归档为 nil: %v", err)
		}
	})

	t.Run("非法状态", func(t *testing.T) {
		dir := t.TempDir()
		writeNamedSyntheticRecord(t, dir, jobFileName(1),
			queuedStoredJob(1, "a", []int64{1}, base))
		writeRawJSONRecord(t, dir, 2, `{
  "version": "numeric-job-v1",
  "id": 2,
  "submitter": "a",
  "request_id": "",
  "seed": 0,
  "values": [1],
  "has_dependency": false,
  "dependency_id": 0,
  "queued_at": "2026-04-08T08:00:00Z",
  "status": "paused"
}`)
		s, err := Open(dir)
		if err == nil {
			_ = s.Close()
			t.Fatal("非法状态必须导致打开失败")
		}
		if s != nil || !strings.Contains(err.Error(), "状态非法") {
			t.Fatalf("应返回原有的非法状态错误且归档为 nil: %v", err)
		}
	})

	t.Run("损坏记录排在冲突之前时先报损坏", func(t *testing.T) {
		dir := t.TempDir()
		// job-...01.json 损坏，文件名排序早于作业 3 的冲突对。
		if err := os.WriteFile(filepath.Join(dir, jobFileName(1)),
			[]byte("{not json"), 0o600); err != nil {
			t.Fatal(err)
		}
		writeNamedSyntheticRecord(t, dir, jobFileName(3),
			queuedStoredJob(3, "a", []int64{1}, base))
		writeNamedSyntheticRecord(t, dir, "job-00000000000000000003-dup.json",
			queuedStoredJob(3, "b", []int64{2}, base))
		s, err := Open(dir)
		if err == nil {
			_ = s.Close()
			t.Fatal("必须打开失败")
		}
		if s != nil || !strings.Contains(err.Error(), "损坏") {
			t.Fatalf("先读到损坏记录时应保留原有损坏错误: %v", err)
		}
	})

	t.Run("同目录另有损坏记录时保留原有损坏错误", func(t *testing.T) {
		// 重复作业号检查只在全部记录都可正常解析、版本及状态合法时生效；
		// 损坏记录即使文件名排在冲突对之后，其原有打开错误仍然有效。
		dir := t.TempDir()
		writeNamedSyntheticRecord(t, dir, "job-00000000000000000001-a.json",
			queuedStoredJob(1, "a", []int64{1}, base))
		writeNamedSyntheticRecord(t, dir, jobFileName(1),
			queuedStoredJob(1, "b", []int64{2}, base))
		if err := os.WriteFile(filepath.Join(dir, jobFileName(2)),
			[]byte("{not json"), 0o600); err != nil {
			t.Fatal(err)
		}
		before := snapshotDir(t, dir)
		s, err := Open(dir)
		if err == nil {
			_ = s.Close()
			t.Fatal("必须打开失败")
		}
		if s != nil || !strings.Contains(err.Error(), "损坏") {
			t.Fatalf("存在损坏记录时应保留原有的损坏错误，而非重复作业号错误: %v", err)
		}
		// 解析阶段失败同样不允许改写目录内任何记录。
		assertDirUnchanged(t, dir, before)
	})
}

// Package numeric 实现本地数值作业的提交、调度、取消与结果归档。
//
// 作业对有符号 64 位整数序列计算总和 (sum) 与平方和 (sum of squares)。
// 本地一次只运行一个作业，其余可运行作业严格按提交先后依次执行；
// 正在等待依赖结果的作业不会挡住后面可运行的作业。
//
// 所有已确认的状态（提交、取消、成功/失败结果）都持久化到目录中，
// 重新 [Store.Open] 同一目录后状态不丢失，幂等请求号继续生效，
// 上次关闭时仍在运行的作业会被标记为失败并阻止其下游继续计算。
package numeric

import (
	"errors"
	"time"
)

// Status 表示作业的状态。
type Status string

const (
	// StatusQueued 表示作业已接受，正在排队（等待计算位置或依赖结果）。
	StatusQueued Status = "queued"
	// StatusRunning 表示作业正在本地计算。
	StatusRunning Status = "running"
	// StatusSucceeded 表示计算成功，且结果已与成功状态一同归档落盘。
	StatusSucceeded Status = "succeeded"
	// StatusFailed 表示作业失败（输入溢出、依赖未通过、重启被中断等）。
	StatusFailed Status = "failed"
	// StatusCanceled 表示作业被提交人取消。
	StatusCanceled Status = "canceled"
)

// WaitReason 描述排队作业当前在等待什么。
type WaitReason string

const (
	// WaitSlot 表示依赖（若有）已产出可使用的结果，作业在等待本地唯一的计算位置。
	WaitSlot WaitReason = "waiting for computation slot"
	// WaitDependency 表示作业在等待其依赖的作业产出结果。
	WaitDependency WaitReason = "waiting for dependency result"
)

// 包级哨兵错误，调用方使用 errors.Is 判断。
var (
	// ErrEmptySequence 表示提交的整数序列为空，该提交被拒绝且不产生记录。
	ErrEmptySequence = errors.New("numeric: 整数序列为空，拒绝提交")
	// ErrNotFound 表示按作业号查不到作业。
	ErrNotFound = errors.New("numeric: 作业不存在")
	// ErrDependencyNotFound 表示提交引用了不存在的依赖作业，提交被拒绝且不产生记录。
	ErrDependencyNotFound = errors.New("numeric: 依赖作业不存在，拒绝提交")
	// ErrInvalidDependency 表示提交的依赖列表不合法：含有零或重复作业号，
	// 或与单依赖方式同时填写了非空列表；该提交被拒绝且不产生记录。
	ErrInvalidDependency = errors.New("numeric: 依赖列表不合法，拒绝提交")
	// ErrIdempotencyConflict 表示同一提交人使用了已存在的幂等请求号，
	// 但提交内容（整数次序、种子或依赖）与原提交不一致，保留原记录。
	ErrIdempotencyConflict = errors.New("numeric: 幂等请求号冲突，提交内容与原提交不一致")
	// ErrNotCancellable 表示作业已处于成功或失败终态，不能取消，原结果保持不变。
	ErrNotCancellable = errors.New("numeric: 作业已结束，不能取消")
	// ErrInvalidTimeRange 表示列举查询的起始时间晚于结束时间。
	ErrInvalidTimeRange = errors.New("numeric: 查询时间范围无效，起始时间晚于结束时间")
	// ErrStoreClosed 表示归档已关闭，不再接受操作。
	ErrStoreClosed = errors.New("numeric: 归档已关闭")
)

// SubmitRequest 是一次作业提交的原始参数。
type SubmitRequest struct {
	// Submitter 为提交人标识，与 RequestID 共同构成幂等键。
	Submitter string
	// RequestID 为幂等请求号，在同一提交人内有效。
	RequestID string
	// Values 为有符号 64 位整数序列，次序属于提交内容的一部分；为空则拒绝提交。
	Values []int64
	// Seed 为种子，属于提交内容的一部分，并参与结果摘要与校验值计算。
	Seed int64
	// HasDependency 为 true 时 DependencyID 指定本作业依赖的已存在作业。
	HasDependency bool
	// DependencyID 是依赖作业号。依赖成功且结果归档后，其总和会作为一个
	// 额外整数（追加在序列末尾）参与本次计算。
	DependencyID uint64
	// Dependencies 为有序的直接上游作业号列表（提交顺序即追加顺序）。
	// 列表中的作业全部成功且归档完整后，本作业才可运行；各上游的总和按
	// 列表顺序逐个追加到原始序列末尾，再计算总和与平方和——不会按上游
	// 完成先后改变输入。列表只能引用提交时已经存在的作业，不能包含零或
	// 重复作业号；与 HasDependency 同时填写非空列表会被拒绝。空列表
	// 表示无依赖，单依赖方式继续可用（单依赖与只含同一作业号的列表等价）。
	Dependencies []uint64
}

// Job 是作业元数据与结果的只读视图。
//
// 所有切片都是内部数据的拷贝，调用方修改返回的 [Job]（含其 [Archive]）
// 不会影响归档内部状态，也不会改变已保存的记录。
type Job struct {
	// ID 为稳定作业号，接受提交后分配，终身不变。
	ID uint64
	// Submitter 为提交人。
	Submitter string
	// RequestID 为幂等请求号。
	RequestID string
	// Seed 为提交时记录的种子。
	Seed int64
	// Values 为提交时记录的原始整数序列（保持原次序）。
	Values []int64
	// HasDependency / DependencyID 记录提交时指定的依赖。
	HasDependency bool
	DependencyID  uint64
	// Dependencies 为提交时记录的有序直接上游作业号（保持提交顺序）；
	// 无依赖时为空。单依赖方式提交的作业在此处表现为只含一个作业号。
	Dependencies []uint64
	// PendingDependencies 仅在排队时有意义：列出尚未成功归档的直接上游
	// 作业号，保持提交时的顺序；为空表示依赖已全部就绪（或本作业无依赖），
	// 排队原因随之变为等待计算位置。
	PendingDependencies []uint64

	// QueuedAt 为接受提交时记录的时间，仅用于时间范围过滤；列举结果的
	// 排列以接受先后（作业号）为准，时钟回拨导致的记录时间早晚不影响次序。
	QueuedAt time.Time
	// StartedAt 为进入运行状态的时间；未运行过为零值。
	StartedAt time.Time
	// FinishedAt 为进入终态（成功/失败/取消）的时间。
	FinishedAt time.Time

	// Status 为当前状态。
	Status Status
	// WaitReason 仅在 Status == StatusQueued 时有意义，说明排队原因。
	WaitReason WaitReason
	// FailureReason 仅在失败时有意义，说明失败原因（含阻断它的上游作业号）。
	FailureReason string
	// BlockerID 在因上游失败/取消而失败时，指出阻断链条的根因作业号；0 表示无。
	BlockerID uint64

	// EffectiveValues 为实际参与计算的输入（成功时）：
	// 原始序列末尾追加依赖作业的总和（若有依赖且其结果已归档）。
	EffectiveValues []int64

	// Archive 仅在 Status == StatusSucceeded 时非空，为完整成功归档。
	Archive *Archive
}

// Archive 是成功作业的完整归档记录：原始参数、实际参与计算的输入摘要、
// 结果摘要、计算日志与校验值。成功状态与归档在同一次原子落盘中可见。
type Archive struct {
	// JobID 为所属作业号。
	JobID uint64 `json:"job_id"`

	// 原始提交参数。
	Submitter string `json:"submitter"`
	RequestID string `json:"request_id"`
	// IdentityRaw 与 jobRecord 同义：标识含非法 UTF-8 字节时按完整字节
	// 保真，保证重开归档后归档中的提交人、请求号与提交时逐字节一致。
	IdentityRaw   *identityRaw `json:"identity_raw,omitempty"`
	Seed          int64        `json:"seed"`
	Values        []int64      `json:"values"`
	HasDependency bool         `json:"has_dependency"`
	DependencyID  uint64       `json:"dependency_id"`
	// Dependencies 为有序直接上游作业号（保持提交顺序）；单依赖方式提交的
	// 作业此处只含一个作业号。上游作业号不参与摘要与校验值。
	Dependencies []uint64 `json:"dependencies,omitempty"`

	// 实际参与计算的输入摘要。
	// EffectiveValues 为实际输入序列（原始序列 + 追加的依赖总和）。
	// InputsDigest 为其与种子的确定性摘要，与作业号、时间无关。
	EffectiveValues []int64 `json:"effective_values"`
	InputsDigest    string  `json:"inputs_digest"`

	// 结果摘要。
	Sum          int64 `json:"sum"`            // 总和
	SumOfSquares int64 `json:"sum_of_squares"` // 平方和
	// ResultDigest 为有效输入、种子与结果的确定性摘要，与作业号、时间无关。
	ResultDigest string `json:"result_digest"`

	// Log 为人类可读的确定性计算日志（不含作业号与时间）。
	Log string `json:"log"`

	// Checksum 为归档校验值，只由有效输入、种子、结果与计算日志决定，
	// 相同有效输入与种子必然得到相同校验值，作业号及时间不影响它。
	Checksum string `json:"checksum"`

	// CompletedAt 为归档完成时间，不参与任何摘要与校验值。
	CompletedAt time.Time `json:"completed_at"`
}

