	g, err := s2.Get(ok.ID)
	if err != nil {
		t.Fatal(err)
	}
	if g.Status != StatusSucceeded || g.Archive == nil {
		t.Fatalf("success record lost: %+v", g)
	}
	if g.Archive.Checksum != wantChecksum || g.Archive.Sum != 6 || g.Archive.SumOfSquares != 14 {
