	if !strings.Contains(gDown.FailureReason, "直接上游作业 "+itoa(mid.ID)) ||
		!strings.Contains(gDown.FailureReason, "阻断根因为作业 "+itoa(up.ID)) {
		t.Fatalf("down 须指出直接上游 mid 与缺失根因 up: %q", gDown.FailureReason)
	}
}

