	if err != nil {
		t.Fatalf("submit mid: %v", err)
	}
	clock.set(time.Date(2026, 10, 3, 9, 55, 0, 0, time.UTC))
	down, err := s.Submit(SubmitRequest{Submitter: "alice", Values: []int64{3}, Dependencies: []uint64{mid.ID}})
	if err != nil {
		t.Fatalf("submit down: %v", err)
	}

