		t.Fatalf("mid 的失败详情应指出直接阻断者 %d，got %q", up.ID, mid2.FailureReason)
	}
	if down2.BlockerID != up.ID {
		t.Fatalf("down 的根因作业号应为 %d，got %d", up.ID, down2.BlockerID)
	}
