137	  "status": "queued"
138	}`)
139		// 作业 4：原始序列有效的排队作业，重开后应照常完成。
140		writeSyntheticRecord(t, dir, &storedJob{
141			id: 4, submitter: "b", requestID: "indep",
142			values:   []int64{1, 2, 3},
143			queuedAt: base.Add(4 * time.Second),
144			status:   StatusQueued,
145		})
146	
147		s, err := Open(dir)
148		if err != nil {
149			t.Fatal(err)
150		}
151		defer s.Close()
152	
153		assertEmptyValuesFailure(t, s, 1, base.Add(time.Second), nil)
154		assertEmptyValuesFailure(t, s, 2, base.Add(2*time.Second), nil)
155		assertEmptyValuesFailure(t, s, 3, base.Add(3*time.Second), nil)
156		for _, id := range []uint64{1, 2, 3} {
157			g, _ := s.Get(id)
158			if g.Seed != int64(6+id) {
159				t.Fatalf("job %d seed changed: %d", id, g.Seed)
160			}
161		}
162	
163		// 无关的有效作业继续遵守已有调度与计算行为。
164		indep := waitStatus(t, s, 4, StatusSucceeded)
165		if indep.Archive.Sum != 6 || indep.Archive.SumOfSquares != 14 {
166			t.Fatalf("unrelated job result=%d,%d want 6,14", indep.Archive.Sum, indep.Archive.SumOfSquares)
167		}
168	
169		// 再次重开：失败结果已保存在目录中，状态、原因与根因保持稳定。
170		if err := s.Close(); err != nil {
171			t.Fatal(err)
172		}
173		s2, err := Open(dir)
174		if err != nil {
175			t.Fatal(err)
176		}
177		defer s2.Close()
178		assertEmptyValuesFailure(t, s2, 1, base.Add(time.Second), nil)
179		assertEmptyValuesFailure(t, s2, 2, base.Add(2*time.Second), nil)
180		assertEmptyValuesFailure(t, s2, 3, base.Add(3*time.Second), nil)
181	}
