183	// 带合法依赖的排队记录原始序列为空时，同样直接失败：不能凭成功上游追加的
184	// 总和补出原始参数后继续计算；被引用的有效上游保留自己的结果。
185	func TestReopenQueuedEmptyValuesWithDependencyFails(t *testing.T) {
186		dir := t.TempDir()
187		base := time.Date(2026, 3, 4, 5, 6, 7, 0, time.UTC)
188		// 作业 1：[1,2] → 总和 3，成功归档。
189		up := syntheticSucceededRecord(t, dir, 1, []int64{1, 2}, []int64{1, 2}, nil, base)
190		if up.archive.Sum != 3 {
191			t.Fatalf("upstream sum=%d want 3", up.archive.Sum)
192		}
193		// 作业 2：排队，原始序列为空，合法依赖作业 1。若凭上游总和补出输入，
194		// 会以 [3] 算出总和 3、平方和 9 的“成功”结果——必须拒绝。
195		writeSyntheticRecord(t, dir, &storedJob{
196			id: 2, submitter: "a", requestID: "empty",
197			dependencies: []uint64{1},
198			queuedAt:     base.Add(2 * time.Second),
199			status:       StatusQueued,
200		})
201	
202		s, err := Open(dir)
203		if err != nil {
204			t.Fatal(err)
205		}
206		defer s.Close()
207	
208		assertEmptyValuesFailure(t, s, 2, base.Add(2*time.Second), []uint64{1})
209	
210		// 被引用的有效上游保留自己的成功结果，不因无效记录而改变。
211		gUp, _ := s.Get(1)
212		if gUp.Status != StatusSucceeded || gUp.Archive == nil || gUp.Archive.Sum != 3 {
213			t.Fatalf("valid upstream must keep its result: status=%s archive=%v", gUp.Status, gUp.Archive)
214		}
215	}
216	
217	// 等待空序列记录结果的下游按既有依赖失败规则被阻断：原因指出直接阻断它的
218	// 上游，根因沿依赖链保留为空序列记录自身的作业号；再下游沿链条继承同一根因。
219	func TestReopenQueuedEmptyValuesBlocksDownstream(t *testing.T) {
220		dir := t.TempDir()
221		base := time.Date(2026, 3, 4, 5, 6, 7, 0, time.UTC)
222		// 作业 1：排队，原始序列为空。
223		writeSyntheticRecord(t, dir, &storedJob{
224			id: 1, submitter: "a", requestID: "empty",
225			queuedAt: base.Add(time.Second),
226			status:   StatusQueued,
227		})
228		// 作业 2：排队等待作业 1。
229		writeSyntheticRecord(t, dir, &storedJob{
230			id: 2, submitter: "a", requestID: "child",
231			values:       []int64{20},
232			dependencies: []uint64{1},
233			queuedAt:     base.Add(2 * time.Second),
234			status:       StatusQueued,
235		})
236		// 作业 3：排队等待作业 2（空序列记录的再下游）。
237		writeSyntheticRecord(t, dir, &storedJob{
238			id: 3, submitter: "a", requestID: "grandchild",
239			values:       []int64{30},
240			dependencies: []uint64{2},
241			queuedAt:     base.Add(3 * time.Second),
242			status:       StatusQueued,
243		})
244	
245		s, err := Open(dir)
246		if err != nil {
247			t.Fatal(err)
248		}
249		defer s.Close()
250	
251		assertEmptyValuesFailure(t, s, 1, base.Add(time.Second), nil)
252	
253		child := waitStatus(t, s, 2, StatusFailed)
254		if child.BlockerID != 1 {
255			t.Fatalf("child blocker=%d want root 1 (the empty-values record itself)", child.BlockerID)
256		}
257		if !strings.Contains(child.FailureReason, "直接上游作业 1") ||
258			!strings.Contains(child.FailureReason, "原始整数序列为空") {
259			t.Fatalf("child must name direct upstream 1 and carry its empty-values reason: %q",
260				child.FailureReason)
261		}
262		if child.Archive != nil || !child.StartedAt.IsZero() {
263			t.Fatalf("blocked child must never compute: started=%s archive=%v", child.StartedAt, child.Archive)
264		}
265	
266		grand := waitStatus(t, s, 3, StatusFailed)
267		if grand.BlockerID != 1 {
268			t.Fatalf("grandchild blocker=%d want root 1 preserved along the chain", grand.BlockerID)
269		}
270		if !strings.Contains(grand.FailureReason, "直接上游作业 2") ||
271			!strings.Contains(grand.FailureReason, "阻断根因为作业 1") {
272			t.Fatalf("grandchild must name direct upstream 2 and root 1: %q", grand.FailureReason)
273		}
274	}
275	
276	// 空序列指没有任何原始整数：[0]、[0,0] 以及包含负数或重复整数的非空序列
277	// 仍是合法输入，不按总和是否为 0 判断有效性，重开后照常计算成功。
278	func TestReopenQueuedZeroValuedSequencesRemainValid(t *testing.T) {
279		dir := t.TempDir()
280		base := time.Date(2026, 3, 4, 5, 6, 7, 0, time.UTC)
281		writeSyntheticRecord(t, dir, &storedJob{
282			id: 1, submitter: "a", requestID: "zero",
283			values:   []int64{0},
284			queuedAt: base.Add(time.Second),
285			status:   StatusQueued,
286		})
287		writeSyntheticRecord(t, dir, &storedJob{
288			id: 2, submitter: "a", requestID: "zeros",
289			values:   []int64{0, 0},
290			queuedAt: base.Add(2 * time.Second),
291			status:   StatusQueued,
292		})
293		writeSyntheticRecord(t, dir, &storedJob{
294			id: 3, submitter: "a", requestID: "neg-dup",
295			values:   []int64{-2, 2, -2},
296			queuedAt: base.Add(3 * time.Second),
297			status:   StatusQueued,
298		})
299	
300		s, err := Open(dir)
301		if err != nil {
302			t.Fatal(err)
303		}
304		defer s.Close()
305	
306		g1 := waitStatus(t, s, 1, StatusSucceeded)
307		if g1.Archive.Sum != 0 || g1.Archive.SumOfSquares != 0 {
308			t.Fatalf("[0] result=%d,%d want 0,0", g1.Archive.Sum, g1.Archive.SumOfSquares)
309		}
310		g2 := waitStatus(t, s, 2, StatusSucceeded)
311		if g2.Archive.Sum != 0 || g2.Archive.SumOfSquares != 0 {
312			t.Fatalf("[0,0] result=%d,%d want 0,0", g2.Archive.Sum, g2.Archive.SumOfSquares)
313		}
314		g3 := waitStatus(t, s, 3, StatusSucceeded)
315		if g3.Archive.Sum != -2 || g3.Archive.SumOfSquares != 12 {
316			t.Fatalf("[-2,2,-2] result=%d,%d want -2,12", g3.Archive.Sum, g3.Archive.SumOfSquares)
317		}
318	}
319	
320	// 已经失败或取消的记录即使原始序列为空，也保留既有终态、原因与根因，
321	// 不被恢复阶段的空序列检查改写。
322	func TestReopenEmptyValuesKeepsExistingTerminalRecords(t *testing.T) {
323		dir := t.TempDir()
324		base := time.Date(2026, 3, 4, 5, 6, 7, 0, time.UTC)
325		failedAt := base.Add(2 * time.Second)
326		writeSyntheticRecord(t, dir, &storedJob{
327			id: 1, submitter: "a", requestID: "f",
328			queuedAt: failedAt, finishedAt: failedAt,
329			status:        StatusFailed,
330			failureReason: "既有的失败原因",
331			blockerID:     9,
332		})
333		writeSyntheticRecord(t, dir, &storedJob{
334			id: 2, submitter: "a", requestID: "c",
335			queuedAt: base.Add(3 * time.Second), finishedAt: base.Add(4 * time.Second),
336			status: StatusCanceled,
337		})
338	
339		s, err := Open(dir)
340		if err != nil {
341			t.Fatal(err)
342		}
343		defer s.Close()
344	
345		gf, _ := s.Get(1)
346		if gf.Status != StatusFailed || gf.BlockerID != 9 || gf.FailureReason != "既有的失败原因" {
347			t.Fatalf("existing failed record must be preserved: status=%s blocker=%d reason=%q",
348				gf.Status, gf.BlockerID, gf.FailureReason)
349		}
350		gc, _ := s.Get(2)
351		if gc.Status != StatusCanceled || gc.BlockerID != 0 || gc.FailureReason != "" {
